# Execute start node: start
execute_node_start() {
    log_step "🚀 Starting Workflow: Start"
    
    # Initialize workflow state
    set_workflow_state "current_node" "start"
    set_workflow_state "status" "running"
    set_workflow_state "start_time" "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
    
    # Set initial variables from node data
    # No initial variables defined
    
    log_info "Workflow started successfully"
}

# Execute agent node: agent_task
execute_node_agent_task() {
    log_step "🤖 Running Agent: Execute Task"
    
    local agent_command="default-agent"
    local agent_args=()
    local agent_timeout=300
    
    # No inputs to prepare
    
    # Execute agent with timeout
    local agent_exit_code=0
    if [[ "$USE_MOCK_TOOLS" == "true" ]]; then
        log_debug "Using mock agent execution"
        local mock_output="Mock output from default-agent"
        local mock_result="Mock result: success"
        
        echo "$mock_output"
        set_workflow_var "agent_output" "$mock_output"
        set_workflow_var "agent_result" "$mock_result"
        agent_exit_code=0
    else
        log_debug "Executing agent: $agent_command with args: ${agent_args[*]}"
        
        # Execute with timeout
        local output
        if output=$(timeout "$agent_timeout" "$agent_command" "${agent_args[@]}" 2>&1); then
            agent_exit_code=0
        else
            agent_exit_code=$?
        fi
        
        # Store output
        set_workflow_var "agent_output" "$output"
        
        # Log output (truncated for readability)
        if [[ ${#output} -gt 200 ]]; then
            log_debug "Agent output (truncated): ${output:0:200}..."
        else
            log_debug "Agent output: $output"
        fi
    fi
    
    # Handle agent result
    if [[ $agent_exit_code -eq 0 ]]; then
        log_info "Agent '$agent_command' completed successfully"
        # No outputs to process
    else
        log_error "Agent '$agent_command' failed with exit code $agent_exit_code"
        return $agent_exit_code
    fi
    
    set_workflow_state "current_node" "agent_task"
}

# Execute answer node: result
execute_node_result() {
    log_step "📤 Providing Answer: Result"
    
    local answer_text="Task completed successfully"
    local final_answer
    final_answer=$(substitute_variables "$answer_text")
    
    echo "=========================="
    echo "WORKFLOW RESULT"
    echo "=========================="
    echo "$final_answer"
    echo "=========================="
    
    log_success "Workflow completed successfully"
    set_workflow_state "current_node" "result"
    set_workflow_state "completed" "true"
}

# =============================================================================
# WORKFLOW EXECUTION FLOW
# =============================================================================

# Execute the complete workflow
execute_workflow() {
    log_info "Starting workflow execution..."
    set_workflow_state "status" "running"
    
    # Generate unique correlation ID for this execution
    local correlation_id=$(date +%s%N | sha256sum | head -c 8)
    
    # Execute start node: start
    if ! execute_node_start "" "$correlation_id"; then
        log_error "Workflow failed at node: start"
        set_workflow_state "status" "failed"
        return 1
    fi

    # Execute agent node: agent_task
    if ! execute_node_agent_task "" "$correlation_id"; then
        log_error "Workflow failed at node: agent_task"
        set_workflow_state "status" "failed"
        return 1
    fi

    # Execute answer node: result
    if ! execute_node_result "" "$correlation_id"; then
        log_error "Workflow failed at node: result"
        set_workflow_state "status" "failed"
        return 1
    fi

    
    log_success "Workflow execution completed"
    set_workflow_state "status" "completed"
}

