# Show help message
show_help() {
    echo "Usage: $0 [OPTIONS]"
    echo ""
    echo "Generated workflow script for: ${WORKFLOW_NAME}"
    echo ""
    echo "Options:"
    echo "    --task_description"
    echo "        What you want the agent to do"
    echo "    --help, -h      Show this help message"
    echo "    --mock         Use mock tools (default: true)"  
    echo "    --real         Use real tools instead of mocks"
    echo "    --verbose      Enable verbose output"
    echo "    --timeout=N    Set timeout in seconds (default: ${AGENT_TIMEOUT})"
    echo ""
    echo "Environment Variables:"
    echo "    USE_MOCK_TOOLS    Set to 'false' to use real tools"
    echo "    VERBOSE          Set to 'true' for debug output"
    echo "    AGENT_TIMEOUT    Timeout in seconds for agent calls"
}

# Initialize workflow with command line arguments
init_workflow() {
    log_info "Initializing workflow: ${WORKFLOW_NAME} v${WORKFLOW_VERSION}"
    
    # Parse command line arguments
    while [[ $# -gt 0 ]]; do
        case $1 in
        --task_description)
            if [[ -z "${2:-}" ]]; then
                log_error "Option --task_description requires a value"
                show_help
                exit 1
            fi
            set_workflow_var "task_description" "$2"
            shift 2
            ;;
        --help|-h)
            show_help
            exit 0
            ;;
        --mock)
            USE_MOCK_TOOLS=true
            export USE_MOCK_TOOLS
            shift
            ;;
        --real)
            USE_MOCK_TOOLS=false
            export USE_MOCK_TOOLS
            shift
            ;;
        --verbose)
            VERBOSE=true
            export VERBOSE
            shift
            ;;
        --timeout=*)
            AGENT_TIMEOUT="${1#*=}"
            export AGENT_TIMEOUT
            shift
            ;;
        *)
            log_error "Unknown option: $1"
            show_help
            exit 1
            ;;
        esac
    done
    
    # Set default values for missing variables
        [[ -z "$(get_workflow_var 'task_description' '')" ]] && set_workflow_var "task_description" ""
    
    log_info "Workflow initialization completed"
}

# =============================================================================
# MAIN EXECUTION
# =============================================================================

# Health check function
health_check() {
    log_info "Running system health check..."
    
    # Check required commands based on mode
    if [[ "$USE_MOCK_TOOLS" != "true" ]]; then
        local missing_tools=()
        
        command -v opencode >/dev/null 2>&1 || missing_tools+=("opencode")
        
        if [[ ${#missing_tools[@]} -gt 0 ]]; then
            log_info "Missing tools (will use mocks): ${missing_tools[*]}"
        else
            log_success "All required tools available"
        fi
    else
        log_info "Running in mock mode - no external tools required"
    fi
}

# Main function
main() {
    health_check
    init_workflow "$@"
    execute_workflow
}

# Run if called directly
if [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then
    main "$@"
fi